solution:
function authorize({ user, action, resource }) {
  if (!user) return false;
  if (user.role === 'admin') return true;
  if (action === 'read') return true;
  if (user.role === 'editor' && resource.ownerId === user.id) return ['update','delete'].includes(action);
  return false;
}
